import { cn } from "@hunt/styled-ui";
import { FlaskConical } from "lucide-react";
import React from "react";
import { BaseRibbon } from "./BaseRibbon";

type PuzzlePrizeRibbonProps = {
  id: string;
  prize: number | string;
  prizeMax?: number;
  solved?: boolean;
  className?: string;
};

export const PuzzlePrizeRibbon = ({
  id,
  prize,
  prizeMax,
  solved,
  className,
}: PuzzlePrizeRibbonProps) => {
  const hoverColors =
    "group-hover/puzzle-card:border-accent group-focus-visible/puzzle-card:border-accent group-hover/puzzle-card:stroke-accent group-focus-visible/puzzle-card:stroke-accent";
  const solvedColors =
    "bg-[#054600] fill-[#054600] text-accent-green border-accent-green stroke-accent-green";
  const unsolvedColors =
    "bg-secondary fill-secondary text-white border-accent-blue stroke-accent-blue";

  return (
    <div
      className={cn("absolute -right-7 top-1/2 -translate-y-1/2", className)}
    >
      <BaseRibbon
        id={id}
        className={cn(
          "py-0.5",
          hoverColors,
          solved ? solvedColors : unsolvedColors,
        )}
        pathClassName={cn(hoverColors, solved ? solvedColors : unsolvedColors)}
      >
        <FlaskConical width={14} strokeWidth={3} className="text-rp" />
        {prize}
        {!solved && typeof prize === "number" && prizeMax && prizeMax > prize
          ? `-${prizeMax}`
          : ""}{" "}
        RP
      </BaseRibbon>
    </div>
  );
};

export default PuzzlePrizeRibbon;
