import { ConditionalTooltip, BadgeSvg } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { Zap, Hourglass, Calendar, Gamepad2 } from "lucide-react";
import React from "react";

type SubmissionType = "auto" | "manual" | "event" | "gameworld" | "interactive";

type TypeStyles = {
  label: string;
  iconColor: string;
  icon: React.ElementType;
};

const SIZE_CLASSES: Record<"sm" | "md", string> = {
  sm: "h-7 w-7",
  md: "h-9 w-9",
};

const getTypeStyles = (submissionType: SubmissionType): TypeStyles => {
  if (submissionType === "auto" || submissionType === "interactive") {
    return {
      label: "Automated task",
      iconColor: "text-[#ECF5FF]",
      icon: Zap,
    };
  }
  if (submissionType === "event") {
    return {
      label: "Event task",
      iconColor: "text-[#EDFFF2]",
      icon: Calendar,
    };
  }
  if (submissionType === "gameworld") {
    return {
      label: "Gameworld task",
      iconColor: "text-black",
      icon: Gamepad2,
    };
  }
  return {
    label: "Manual task",
    iconColor: "text-[#FFEDF2]",
    icon: Hourglass,
  };
};

const tooltipText = (submissionType: SubmissionType): string => {
  if (submissionType === "auto") {
    return "Instant feedback & RP";
  }
  if (submissionType === "manual") {
    return "Will require staff review";
  }
  if (submissionType === "gameworld") {
    return "MonQuest Task";
  }
  return "In-person event";
};

type TaskSubmissionIconProps = {
  submissionType: SubmissionType;
  size?: "sm" | "md";
  className?: string;
  badgeClassName?: string;
  isInline?: boolean;
  disabled?: boolean;
};

export const TaskSubmissionIcon = ({
  submissionType,
  size = "md",
  className,
  badgeClassName,
  disabled = false,
  isInline = false,
}: TaskSubmissionIconProps) => {
  const { iconColor, icon: Icon, label } = getTypeStyles(submissionType);
  const iconStrokeClass =
    submissionType === "gameworld" && disabled ? "text-white" : iconColor;
  const tooltip = tooltipText(submissionType);
  return (
    <ConditionalTooltip
      className={cn(
        "bg-neutral-300 text-black border-2 rounded-md",
        submissionType === "auto" || submissionType === "interactive"
          ? "border-accent-blue"
          : submissionType === "event"
            ? "border-accent-green"
            : submissionType === "gameworld"
              ? "border-accent-yellow"
              : "border-accent-red",
      )}
      tooltip={isInline && tooltip}
    >
      <span
        className={cn(
          "relative inline-flex items-center justify-center",
          SIZE_CLASSES[size],
          className,
        )}
        role={isInline ? "img" : undefined}
        aria-hidden={!isInline}
        aria-label={isInline ? label : undefined}
      >
        <BadgeSvg
          state={submissionType}
          disabled={disabled}
          className={cn(
            disabled &&
              "group-hover/task-submission-filter:fill-[#B7BEC9] group-focus-visible/task-submission-filter:fill-[#B7BEC9]",
            badgeClassName,
          )}
        />
        <Icon
          className={cn(
            "relative z-10",
            size === "sm" ? "h-3 w-3" : "h-4 w-4",
            iconStrokeClass,
          )}
          strokeWidth={2.5}
        />
      </span>
    </ConditionalTooltip>
  );
};

export default TaskSubmissionIcon;
