import {
  type PuzzleState,
  type TeamHuntState,
  newClient,
} from "@hunt/public-client";
import { FlaskConical, LockOpen } from "lucide-react";
import React, {
  type MouseEventHandler,
  type Ref,
  useCallback,
  useState,
} from "react";
import { type PhysicalPresenceRequirement } from "../client/all_puzzles_types";
import apiUrl from "../utils/apiUrl";
import { IS_STATIC_SITE, staticDisabledMessage } from "../utils/staticSite";
import { NSFWIndicator } from "./NSFWIndicator";
import { PHYSICAL_PRESENCE_TOOLTIP_MAP } from "./PuzzleAndTaskDisplay/PhysicalPresenceIndicator";
import { useTeamState } from "./TeamStateProvider";
import {
  stopUnlockDialogClick,
  unlockCancelButtonClass,
  unlockDialogClassName,
  unlockHeaderBorderClass,
  unlockHeaderInnerClass,
  unlockHeaderTextClass,
  unlockMessageClass,
  unlockMessageErrorClass,
  unlockMessageWarningClass,
  unlockPrimaryButtonClass,
} from "./unlockModalStyles";

export type PuzzleBaseState = {
  slug: string;
  title: string;
  state: "unlocked" | "unlockable" | "locked";
  answer?: string;
  solved?: boolean;
  desc?: string;
  unlock_cost?: number;
  is_overworld_feeder: boolean;
};

export type PuzzleStateHandle = [
  PuzzleBaseState,
  (handleApiResponse: PuzzleState) => void,
];

const currentOverworldWidth = (teamState: TeamHuntState): number => {
  return Object.values(teamState.puzzles).filter(
    (puzzle) =>
      puzzle.is_overworld_feeder &&
      !puzzle.answer &&
      puzzle.locked === "unlocked",
  ).length;
};

export const PuzzleUnlockModal = React.forwardRef(
  function PuzzleUnlockModalInner(
    {
      onDismiss,
      cost,
      stateHandle,
      physicalPresenceRequirement,
      nsfw,
      isLoading = false,
    }: {
      onDismiss: () => void;
      cost: number;
      stateHandle: PuzzleStateHandle;
      physicalPresenceRequirement?: PhysicalPresenceRequirement;
      nsfw?: boolean;
      isLoading?: boolean;
    },
    ref: Ref<HTMLDialogElement>,
  ) {
    const teamState = useTeamState();
    const { currency, max_overworld_width } = teamState;
    const [{ slug, title, desc, is_overworld_feeder }, setApiState] =
      stateHandle;
    const [fetching, setFetching] = useState<boolean>(false);
    const [errorMessage, setErrorMessage] = useState<string | null>(null);
    const isStaticSite = IS_STATIC_SITE;
    const onUnlock: MouseEventHandler<HTMLButtonElement> = useCallback(() => {
      if (fetching) return;
      if (IS_STATIC_SITE) {
        setErrorMessage(staticDisabledMessage("Unlocks"));
        return;
      }
      setFetching(true);
      setErrorMessage(null);
      const apiClient = newClient(apiUrl(), undefined);
      apiClient
        .unlockPuzzle({ params: { slug } })
        .then((result) => {
          setFetching(false);
          if (result.status === 200) {
            setApiState(result.body);
            onDismiss();
            setErrorMessage(null);
            return;
          }
          if (result.status === 400) {
            if (result.body.code === "OVERWORLD_FEEDER_LIMIT_REACHED") {
              setErrorMessage(
                `You have reached the maximum number of unlocked overworld puzzles. Please solve one before unlocking another.`,
              );
            } else {
              setErrorMessage(
                `Error encountered while unlocking ${title}. Please refresh the page and try again.`,
              );
            }
            return;
          }
          setErrorMessage(
            `Error encountered while unlocking ${title}. Please refresh the page and try again.`,
          );
        })
        .catch((err: unknown) => {
          console.error("Failed to unlock puzzle", err);
          setFetching(false);
          setErrorMessage(
            `Error encountered while unlocking ${title}. Please refresh the page and try again.`,
          );
        });
    }, [fetching, onDismiss, setApiState, slug, title]);

    const curr_overworld_width = currentOverworldWidth(teamState);

    let modalMessage = (
      <p className={unlockMessageClass}>
        Unlocking this puzzle will spend {cost} of your team&apos;s {currency}{" "}
        available research point{currency === 1 ? "" : "s"}.
      </p>
    );
    let enabled = true;
    if (isStaticSite) {
      enabled = false;
      modalMessage = (
        <p className={unlockMessageWarningClass}>
          {staticDisabledMessage("Unlocks")}
        </p>
      );
    } else if (cost > currency) {
      modalMessage = (
        <p className={unlockMessageErrorClass}>
          You cannot unlock this puzzle because you do not have enough research
          points.
        </p>
      );
      enabled = false;
    } else if (
      is_overworld_feeder &&
      max_overworld_width <= curr_overworld_width
    ) {
      enabled = false;
      modalMessage = (
        <p className={unlockMessageErrorClass}>
          You cannot befriend more than {max_overworld_width} Puzzmon at a time.
          Solve more puzzles to unlock this puzzle.
        </p>
      );
    }

    const handleDialogClick: MouseEventHandler<HTMLDialogElement> = useCallback(
      (event) => {
        if (event.target === event.currentTarget) {
          event.stopPropagation();
          onDismiss();
        }
      },
      [onDismiss],
    );

    return (
      // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-noninteractive-element-interactions
      <dialog
        ref={ref}
        className={unlockDialogClassName}
        aria-modal="true"
        onClick={handleDialogClick}
      >
        {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */}
        <div
          className="flex max-w-full flex-col gap-5"
          onClick={stopUnlockDialogClick}
        >
          <div className={unlockHeaderBorderClass}>
            <div className={unlockHeaderInnerClass}>
              <FlaskConical className="h-6 w-6 text-rp" />
              <span className={unlockHeaderTextClass}>Spend {cost} RP?</span>
            </div>
          </div>
          <div className="flex flex-col gap-1 whitespace-normal px-4">
            {isLoading ? (
              <h1 className="font-headline text text-white italic">
                Loading puzzle details...
              </h1>
            ) : (
              <div className="flex items-center gap-2">
                <h1 className="font-headline text text-white">
                  Unlock puzzle{" "}
                  <span className="font-extrabold text-accent">{title}</span>?
                </h1>
                {nsfw && (
                  <NSFWIndicator
                    size="xl"
                    className="transform-gpu drop-shadow-[0_2px_2px_rgba(0,0,0,0.5)]"
                    iconClassName="text-red-500"
                  />
                )}
              </div>
            )}
            {!isLoading && desc ? (
              <p className="text-[#C9DAFF] text-base sm:text-lg italic">
                {desc}
              </p>
            ) : undefined}
            {!isLoading && physicalPresenceRequirement && (
              <p className={unlockMessageWarningClass}>
                <span>
                  {PHYSICAL_PRESENCE_TOOLTIP_MAP[physicalPresenceRequirement]}
                </span>
                {(physicalPresenceRequirement === "required" ||
                  physicalPresenceRequirement === "required_with_pickup") && (
                  <span>
                    <br />
                    Do not unlock if your team is fully remote.
                  </span>
                )}
              </p>
            )}
            {modalMessage}
            {errorMessage ? (
              <p className={unlockMessageErrorClass}>{errorMessage}</p>
            ) : null}
          </div>
          <div className="flex flex-wrap justify-end gap-3 sm:flex-nowrap">
            <button
              className={unlockCancelButtonClass}
              onClick={onDismiss}
              disabled={fetching}
              type="button"
            >
              Cancel
            </button>
            <button
              className={unlockPrimaryButtonClass}
              onClick={onUnlock}
              disabled={fetching || !enabled || isLoading}
              type="button"
            >
              <LockOpen className="h-5 w-5 text-[#153A62]" />
              Unlock
            </button>
          </div>
        </div>
      </dialog>
    );
  },
);
