import {
  CheckCircle,
  Copy,
  Hourglass,
  Lock,
  Puzzle,
  TriangleAlert,
} from "lucide-react";
import React, { useCallback, useRef, useState } from "react";
import MagnifyingGlass from "../../assets/MagnifyingGlass";
import { type PhysicalPresenceRequirement } from "../../client/all_puzzles_types";
import { IS_STATIC_SITE } from "../../utils/staticSite";
import { PuzzleUnlockModal } from "../PuzzleUnlockModal";
import { useTeamState } from "../TeamStateProvider";
import { BaseRibbon } from "./BaseRibbon";
import { PhysicalPresenceIndicator } from "./PhysicalPresenceIndicator";
import { PuzzlePrizeRibbon } from "./PuzzlePrizeRibbon";
import { TaskSubmissionIcon } from "./TaskSubmissionIcon";

export type LockState = "unlockable" | "unlocked" | "locked";
export type LockOrSolvedState =
  | "solved"
  | "unlockable"
  | "unlocked"
  | "locked"
  | "pending_grade";

type PuzzleBaseState = {
  slug: string;
  title: string;
  state: "unlocked" | "unlockable" | "locked";
  answer?: string;
  solved?: boolean;
  desc?: string;
  unlock_cost?: number;
  is_overworld_feeder: boolean;
};

type PuzzleStateHandle = [
  PuzzleBaseState,
  (handleApiResponse: PuzzleState) => void,
];

export function usePuzzleState(
  wsEpoch: number,
  wsState: PuzzleBaseState,
): PuzzleStateHandle {
  const [apiState, setApiState] = useState<PuzzleState | null>(null);

  let finalState: PuzzleBaseState = wsState;
  if (apiState && apiState.epoch > wsEpoch) {
    finalState = {
      ...finalState,
      answer: apiState.answer,
      solved: apiState.solved,
      state: apiState.locked,
      unlock_cost: apiState.unlock_cost,
      is_overworld_feeder: apiState.is_overworld_feeder,
    };
  }
  return [finalState, setApiState];
}

export const PuzzleIconFromState = ({
  state,
  isResearchTask,
  className,
  strokeWidth,
  size = "sm",
}: {
  state: LockOrSolvedState;
  isResearchTask?: boolean;
  className?: string;
  strokeWidth?: number;
  size?: "sm" | "lg";
}) => {
  if (state === "pending_grade") {
    return (
      <Hourglass
        className={cn(
          `inline-block transition-colors text-red-500`,
          size === "sm" ? "h-6 w-6" : "h-12 w-12",
          className,
        )}
        strokeWidth={strokeWidth}
      />
    );
  } else if (isResearchTask && state === "unlocked") {
    return (
      <MagnifyingGlass
        className={cn(
          `inline-block transition-colors stroke-accent`,
          size === "sm" ? "h-6 w-6" : "h-12 w-12",
          className,
        )}
      />
    );
  } else if (state === "unlockable") {
    return (
      <Lock
        className={cn(
          `inline-block transition-colors text-gray-500`,
          size === "sm" ? "h-6 w-6" : "h-12 w-12",
          className,
        )}
        strokeWidth={strokeWidth}
      />
    );
  } else if (state === "unlocked") {
    return (
      <Puzzle
        className={cn(
          `inline-block transition-colors text-blue-500`,
          size === "sm" ? "h-6 w-6" : "h-12 w-12",
          className,
        )}
        strokeWidth={strokeWidth}
      />
    );
  } else if (state === "solved") {
    return (
      <CheckCircle
        className={cn(
          `inline-block transition-colors text-accent-green`,
          size === "sm" ? "h-6 w-6" : "h-12 w-12",
          className,
        )}
        strokeWidth={strokeWidth}
      />
    );
  } else {
    return null;
  }
};

export const PuzzleIcon = ({
  lockState,
  solved,
  className = "",
  strokeWidth,
  size = "sm",
}: {
  lockState: LockState;
  solved?: boolean;
  className?: string;
  strokeWidth?: number;
  size?: "sm" | "lg";
}) => {
  let state: LockOrSolvedState = lockState;

  if (solved) {
    state = "solved";
  }

  return (
    <PuzzleIconFromState
      state={state}
      className={className}
      strokeWidth={strokeWidth}
      size={size}
    />
  );
};

