type StatusIconProps = {
  lockState: "locked" | "unlocked" | "unlockable";
  isResearchTask?: boolean;
  answer?: string;
  solved?: boolean;
  taskSubmissionState?: "submittable" | "pending_grade" | "complete";
};

const StatusIcon = ({
  lockState,
  isResearchTask,
  answer,
  solved,
  taskSubmissionState,
}: StatusIconProps) => {
  // Determine the display state based on task submission state
  let displayState: LockOrSolvedState;
  if (taskSubmissionState === "pending_grade") {
    displayState = "pending_grade";
  } else if (solved ?? answer) {
    displayState = "solved";
  } else {
    displayState = lockState;
  }

  return (
    <div className="w-32 h-full shrink-0 flex items-center pl-4 rounded-l-[10px] bg-secondary box-border [clip-path:polygon(0_0,100%_0,64%_100%,0%_100%)]">
      <div className="relative h-fit w-fit">
        {/* Puzzle status icon */}
        <PuzzleIconFromState
          state={displayState}
          className={cn(
            "relative w-11 h-11 z-10",
            lockState === "unlockable" && "text-accent-blue",
            lockState === "unlocked" &&
              !answer &&
              displayState !== "pending_grade" &&
              "text-accent stroke-accent",
            (solved ?? answer) && "text-accent-green stroke-accent-green",
            displayState === "pending_grade" && "text-red-500 stroke-red-500",
          )}
          isResearchTask={isResearchTask}
        />
        {/* The status icon's shadow. */}
        <PuzzleIconFromState
          state={displayState}
          className="absolute left-1 top-1.5 w-11 h-11 text-[#0B1D31] stroke-[#0B1D31] z-0"
          isResearchTask={isResearchTask}
        />
      </div>
    </div>
  );
};

type CopyOnClickRibbonProps = {
  children: string;
  className?: string;
};

const CopyOnClickRibbon = ({ children, className }: CopyOnClickRibbonProps) => {
  const [showCopiedMessage, setShowCopiedMessage] = useState(false);
  const copiedMessageTimer = useRef<number | undefined>();

  const handleCopy = useCallback(() => {
    void navigator.clipboard.write([
      new ClipboardItem({ "text/plain": children }),
    ]);
    setShowCopiedMessage(true);
    copiedMessageTimer.current = window.setTimeout(() => {
      setShowCopiedMessage(false);
    }, 3000);
  }, [children]);

  return (
    <div
      className={cn(
        "absolute -right-4 top-1/2 -translate-y-1/2 group/copy-ribbon transition-[right]",
        !showCopiedMessage && "hover:-right-9",
      )}
    >
      <button className="relative flex items-center gap-1" onClick={handleCopy}>
        <div className="absolute left-0">
          <Copy width={18} className="text-accent-green" />
        </div>
        <BaseRibbon
          id={children}
          className={cn(
            "font-mono bg-[#054600] text-accent-green border-accent-green transition-[margin-left]",
            !showCopiedMessage && "group-hover/copy-ribbon:ml-5",
            className,
          )}
          pathClassName="fill-[#054600] stroke-accent-green"
        >
          {children}
        </BaseRibbon>
      </button>
      {showCopiedMessage && (
        <div className="absolute -top-4 -left-10 -rotate-[15deg] text-accent font-bold">
          Copied!
        </div>
      )}
    </div>
  );
};

type AnswerRibbonProps = {
  answer?: string;
};

const AnswerRibbon = ({ answer }: AnswerRibbonProps) => {
  return (
    <div className="group/ribbon">
      {/* Answer Ribbon */}
      {answer && <CopyOnClickRibbon>{answer}</CopyOnClickRibbon>}
    </div>
  );
};

type PuzzleCardContentProps = {
  icon: React.ReactNode;
  title: string;
  desc: string;
  className?: string;
  meta?: boolean;
  capstone?: boolean;
  nsfw?: boolean;
  physicalPresenceRequirement?: PhysicalPresenceRequirement;
  prize?: number | string;
  prizeMax?: number;
  solved?: boolean;
  answer?: string;
  submissionType?: "auto" | "manual" | "event" | "gameworld" | "interactive";
};

const PuzzleCardContent = ({
  icon,
  title,
  desc,
  meta,
  capstone,
  nsfw,
  physicalPresenceRequirement,
  prize,
  prizeMax,
  solved,
  answer,
  submissionType,
}: PuzzleCardContentProps) => {
  const isResearchTask = prize !== undefined;

  return (
    <div
      className={cn(
        "relative h-[72px] w-full flex items-center rounded-xl bg-primary border-4 border-secondary hover:border-accent group-focus-visible/puzzle-card:border-accent text-left w-full min-w-[520px]",
      )}
    >
      {icon}
      <SlantDecoration className="absolute left-16" />

      {/* Text */}
      <div className="flex flex-col w-full text-white pl-2 min-w-0">
        <div className="flex gap-1 items-center justify-between">
          <div
            className={cn(
              "text-xl font-title flex gap-3 items-center",
              isResearchTask && "mr-24",
            )}
          >
            {title}
            {meta && (
              <div className="font-body bg-secondary border-[3px] border-accent text-accent text-sm px-4 rounded-full">
                {capstone ? "CAPSTONE" : "META"}
              </div>
            )}
            {nsfw && (
              <BadgeWithTooltip
                icon={TriangleAlert}
                tooltip="Mature content"
                label="Mature content"
                tooltipClassName="border-accent-red"
                badgeClassname="fill-red-600"
                iconClassName="text-white mb-[3px]"
              />
            )}
            {physicalPresenceRequirement && (
              <PhysicalPresenceIndicator
                physicalPresenceRequirement={physicalPresenceRequirement}
              />
            )}
          </div>
          {/* The only purpose of this is to determine how much space the description has. The actual answer
           * is displayed as an absolutely positioned element. */}
          {answer && (
            <div
              className="text-xs font-bold font-mono whitespace-nowrap select-none pl-4 invisible"
              aria-hidden
            >
              {answer}
            </div>
          )}
        </div>
        {desc && (
          <OverflowTooltip tooltip={desc}>
            <div
              className={cn(
                "text-lg font-body -ml-4 pr-1 overflow-hidden text-ellipsis whitespace-nowrap",
                isResearchTask ? "mr-24" : "",
              )}
            >
              {desc}
            </div>
          </OverflowTooltip>
        )}
      </div>

      {submissionType && (
        <TaskSubmissionIcon
          submissionType={submissionType}
          className={cn(
            "absolute right-14 top-1/2 -translate-y-1/2",
            // There probably won't be any prizes greater than 9, but if there are, we need to give it more space.
            prize && typeof prize === "number" && prize > 9 && "right-14",
          )}
          isInline
          size="sm"
        />
      )}

      {/* Prize Ribbon. We put this ribbon inside the puzzle card content so that the border color updates as we hover over the puzzle card. */}
      {isResearchTask && (
        <PuzzlePrizeRibbon
          id={title}
          prize={prize}
          prizeMax={prizeMax}
          solved={solved}
        />
      )}
    </div>
  );
};

const PuzzleCard = ({
  lockState,
  answer,
  title,
  slug,
  round_slug,
  desc,
  unlock_cost,
  is_overworld_feeder,
  nsfw,
  physicalPresenceRequirement,
  solved,
  prize,
  prizeMax,
  meta = false, // Make meta tiles visually distinct without an outer wrapper
  capstone = false, // If true, this puzzle is the capstone puzzle for the round in the overworld
  submissionType,
  taskSubmissionState,
}: {
  lockState: LockState;
  answer?: string;
  title: string;
  slug: string;
  round_slug?: string;
  desc?: string;
  unlock_cost?: number;
  is_overworld_feeder: boolean;
  nsfw?: boolean;
  physicalPresenceRequirement?: PhysicalPresenceRequirement;
  prize?: number | string;
  prizeMax?: number;
  solved?: boolean;
  meta?: boolean;
  capstone?: boolean;
  submissionType?: "auto" | "manual" | "event" | "gameworld" | "interactive";
  taskSubmissionState?: "submittable" | "pending_grade" | "complete";
}) => {
  const { epoch } = useTeamState();
  const modalRef = useRef<HTMLDialogElement>(null);

  const handleCardClick = useCallback(() => {
    if (!IS_STATIC_SITE && lockState === "unlockable") {
      modalRef.current?.showModal();
    }
  }, [lockState]);

  const dismissModal = useCallback(() => modalRef.current?.close(), []);

  const puzzleStateHandle = usePuzzleState(epoch, {
    slug,
    title,
    state: lockState,
    answer,
    solved,
    desc,
    unlock_cost,
    is_overworld_feeder,
  });
  const [puzzleState] = puzzleStateHandle;

  if (lockState === "locked") return undefined;

  const cost = puzzleState.unlock_cost ?? 1;
  const description = puzzleState.desc || "";

  const isResearchTask =
    taskSubmissionState !== undefined ||
    submissionType !== undefined ||
    round_slug === "research_tasks";

  // Unlocked tiles are links; unlockable tiles open the modal.
  if (puzzleState.state === "unlocked") {
    const puzzleUrl = isResearchTask
      ? `/research_tasks/${slug}`
      : round_slug === "atlas_of_mosaics"
        ? `/rounds/atlas_of_mosaics?puzzle=${encodeURIComponent(slug)}`
        : `/puzzles/${slug}`;
    return (
      <div className="relative">
        <a
          href={puzzleUrl}
          role="button"
          className="group/puzzle-card text-black"
        >
          <PuzzleCardContent
            icon={
              <StatusIcon
                lockState={lockState}
                answer={answer}
                solved={solved}
                isResearchTask={prize !== undefined}
                taskSubmissionState={taskSubmissionState}
              />
            }
            title={title}
            desc={description}
            meta={meta}
            capstone={capstone}
            nsfw={nsfw}
            physicalPresenceRequirement={physicalPresenceRequirement}
            prize={prize}
            prizeMax={prizeMax}
            solved={solved}
            answer={answer}
            submissionType={submissionType}
          />
        </a>
        {/* Answer ribbon. We put this ribbon outside of the puzzle card content because it is interactive.
          This means that the border color does not update as we hover over the puzzle card, but we could not figure out how to get both easily. */}
        <AnswerRibbon answer={answer} />
      </div>
    );
  }

  return (
    <div
      className="relative cursor-pointer"
      onClick={handleCardClick}
      onKeyDown={(e) => {
        if (e.key === "Enter") {
          handleCardClick();
        }
      }}
      role="button"
      tabIndex={0}
    >
      <div className="group/puzzle-card">
        <PuzzleCardContent
          icon={
            <StatusIcon
              lockState={lockState}
              answer={answer}
              solved={solved}
              isResearchTask={prize !== undefined}
              taskSubmissionState={taskSubmissionState}
            />
          }
          title={title}
          desc={description}
          meta={meta}
          capstone={capstone}
          nsfw={nsfw}
          physicalPresenceRequirement={physicalPresenceRequirement}
          prize={prize}
          prizeMax={prizeMax}
          solved={solved}
          submissionType={submissionType}
        />
      </div>
      {!IS_STATIC_SITE && puzzleState.state === "unlockable" && (
        <PuzzleUnlockModal
          ref={modalRef}
          stateHandle={puzzleStateHandle}
          onDismiss={dismissModal}
          cost={cost}
          physicalPresenceRequirement={physicalPresenceRequirement}
          nsfw={nsfw}
        />
      )}
    </div>
  );
};

export default PuzzleCard;
