import { BadgeWithTooltip } from "@hunt/shadcn";
import { type LucideIcon, Package, WifiOff, UserStar } from "lucide-react";
import React from "react";
import { type PhysicalPresenceRequirement } from "../../client/all_puzzles_types";

export const PHYSICAL_PRESENCE_TOOLTIP_MAP: Record<
  PhysicalPresenceRequirement,
  string
> = {
  required: "Physical presence at MIT is required.",
  required_with_pickup:
    "Physical presence at MIT is required.\nThere is a physical pickup.",
  recommended: "MIT presence recommended, but not strictly required.",
  recommended_with_pickup:
    "MIT presence recommended, but not strictly required.\nThere is a physical pickup.",
};

type PhysicalPresenceIndicatorProps = {
  className?: string;
  physicalPresenceRequirement: PhysicalPresenceRequirement;
};

export const PhysicalPresenceIndicator: React.FC<
  PhysicalPresenceIndicatorProps
> = ({ className = "", physicalPresenceRequirement }) => {
  const requiresPhysicalPresence =
    physicalPresenceRequirement === "required" ||
    physicalPresenceRequirement === "required_with_pickup";
  const recommendedPhysicalPresence =
    physicalPresenceRequirement === "recommended" ||
    physicalPresenceRequirement === "recommended_with_pickup";
  const hasPickupInvolved =
    physicalPresenceRequirement === "required_with_pickup" ||
    physicalPresenceRequirement === "recommended_with_pickup";

  const icons: LucideIcon[] = [];
  const tooltip = PHYSICAL_PRESENCE_TOOLTIP_MAP[physicalPresenceRequirement];

  if (requiresPhysicalPresence) {
    icons.push(WifiOff);
  }
  if (recommendedPhysicalPresence) {
    icons.push(UserStar);
  }
  if (hasPickupInvolved) {
    icons.push(Package);
  }

  return (
    <BadgeWithTooltip
      icon={icons}
      tooltip={tooltip}
      label={tooltip}
      className={className}
      tooltipClassName="border-secondary"
      badgeClassname="fill-accent"
      iconClassName="text-secondary"
    />
  );
};

export default PhysicalPresenceIndicator;
